CREATE TABLE event_forecast_requests(id TEXT PRIMARY KEY, dataset_id TEXT NOT NULL REFERENCES datasets(id), event_id TEXT NOT NULL REFERENCES neso_events(id), replay_date TEXT NOT NULL, forecast_origin TEXT NOT NULL, policy_json TEXT NOT NULL, coverage_id TEXT NOT NULL REFERENCES objects(sha256));
CREATE TABLE event_forecast_models(fingerprint TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES event_forecast_requests(id), algorithm TEXT NOT NULL, version TEXT NOT NULL UNIQUE, config_json TEXT NOT NULL, artifact_id TEXT NOT NULL REFERENCES objects(sha256), predictions_id TEXT NOT NULL REFERENCES objects(sha256), evaluation_id TEXT NOT NULL REFERENCES objects(sha256), information_cutoff TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE event_forecast_metrics(model_id TEXT NOT NULL REFERENCES event_forecast_models(fingerprint), scope TEXT NOT NULL CHECK(scope IN ('validation','holdout','full_day','event_window')), household_id TEXT NOT NULL, mae_kw REAL NOT NULL CHECK(mae_kw>=0), rmse_kw REAL NOT NULL CHECK(rmse_kw>=mae_kw), observations INTEGER NOT NULL CHECK(observations>0), PRIMARY KEY(model_id,scope,household_id));
CREATE TABLE event_forecast_status(request_id TEXT PRIMARY KEY REFERENCES event_forecast_requests(id), state TEXT NOT NULL CHECK(state IN ('available','unavailable')), reason TEXT NOT NULL);
CREATE TABLE event_active_models(request_id TEXT PRIMARY KEY REFERENCES event_forecast_requests(id), model_id TEXT NOT NULL REFERENCES event_forecast_models(fingerprint));
CREATE INDEX event_forecast_lookup ON event_forecast_models(request_id,algorithm);
